```python
def apply_ops(state, ops):
    s = list(state)
    for op in ops:
        if op[0] == 'SWAP':
            _, i, j = op
            s[i], s[j] = s[j], s[i]
        elif op[0] == 'REVERSE':
            _, a, b = op
            s[a:b+1] = s[a:b+1][::-1]
        elif op[0] == 'ROTATE_LEFT':
            _, k = op
            s = s[k:] + s[:k]
        elif op[0] == 'ROTATE_RIGHT':
            _, k = op
            s = s[-k:] + s[:-k]
    return s
```

