def eval_circuit(inputs, gates):
    vals = dict(inputs)
    for name, op, args in gates:
        a = vals[args[0]]
        b = vals[args[1]] if len(args) > 1 else None
        if op == 'AND':
            vals[name] = a & b
        elif op == 'OR':
            vals[name] = a | b
        elif op == 'XOR':
            vals[name] = a ^ b
        elif op == 'NOT':
            vals[name] = 1 - a
        elif op == 'NAND':
            vals[name] = 1 - (a & b)
        elif op == 'NOR':
            vals[name] = 1 - (a | b)
    return vals
```

