def ticket_total(ages, base_price, child_max=12, senior_min=65, child_pct=0.5, senior_pct=0.75):
    total = 0
    for age in ages:
        if age < child_max:
            total += base_price * child_pct
        elif age >= senior_min:
            total += base_price * senior_pct
        else:
            total += base_price
    return total
