```python
def compress(s):
    if not s:
        return ''
    out = []
    current = s[0]
    count = 1
    for c in s[1:]:
        if c == current:
            count += 1
        else:
            out.append(f'{current}{count}')
            current = c
            count = 1
    out.append(f'{current}{count}')
    return ''.join(out)
```

